#!/bin/zsh
# Copies the benchmark tools, dev tools, agent configs and results of the v4 study to DEST
# (default: next to the user's groupA folder). The copy has the layout of TAG/arena; its scripts use paths relative
# to their own location. README.md and runs.md come from drafts/, RESULTS.md is generated by make_v4_tables.py.
SRC=/Users/halit/Desktop/statistics/TAG/arena
DEST=${1:-/Users/halit/Desktop/statistics/groupA_code/experiments_v4}
mkdir -p $DEST/results $DEST/src $DEST/dev
cp -R $SRC/agents $DEST/
cp -R $SRC/src/arena $SRC/src/check $SRC/src/refv2 $DEST/src/
cp -R $SRC/dev/groupA $SRC/dev/README.md $DEST/dev/
mkdir -p $DEST/tools
sed -e 's|^cd /Users/halit/Desktop/statistics/TAG$|cd "$(dirname "$0")/../.."|' \
    -e 's|/private/tmp/claude-501/[^ ]*/scratchpad|${TMPDIR:-/tmp}|g' \
    -e 's|^export PATH=/opt/homebrew/opt/openjdk/bin:\$PATH$|# needs Java 21+ on the PATH|' \
    $SRC/tools/quiet_probe.sh > $DEST/tools/quiet_probe.sh
chmod +x $DEST/tools/quiet_probe.sh
cp $SRC/tab.py $SRC/compare.py $SRC/summarise.py $SRC/types.py $SRC/pooled.py $SRC/factorial.py $SRC/mk.py \
   $SRC/make_v4_tables.py $DEST/
cp $SRC/drafts/experiments_v4_README.md $DEST/README.md
cp $SRC/drafts/runs.md $DEST/runs.md
cp $SRC/results/*.csv $SRC/results/*.log $SRC/results/*.err $SRC/results/*.txt $DEST/results/ 2>/dev/null
for f in run.sh batch.sh build.sh battery_guard.sh; do
  sed -e 's|^cd /Users/halit/Desktop/statistics/TAG/arena/results$|cd "$(dirname "$0")/results"|' \
      -e 's|^cd /Users/halit/Desktop/statistics/TAG$|cd "$(dirname "$0")/.."|' \
      -e 's|^SNAPROOT=.*|SNAPROOT=${TMPDIR:-/tmp}/arena-snap|' \
      -e 's|^LOG=/Users/halit/Desktop/statistics/TAG/arena/results/battery_guard.log$|LOG="$(dirname "$0")/results/battery_guard.log"|' \
      -e 's|^export PATH=/opt/homebrew/opt/openjdk/bin:\$PATH$|# needs Java 21+ on the PATH|' \
      $SRC/$f > $DEST/$f
  chmod +x $DEST/$f
done
(cd $DEST/results && {
  echo "# Sushi Go agent v4 – experiment results"
  echo
  echo "Generated by \`make_v4_tables.py\` from the CSV files in \`results/\` (see README.md for the setup and"
  echo "\`runs.md\` for the agent files, seed and opponents of every run). † = run played before the canonical deals"
  echo "(19 October, 01:37): its differences to other runs are two-sample, not paired, comparisons."
  echo
  python3 ../make_v4_tables.py
} > ../RESULTS.md)
echo "packaged into $DEST"
grep -rn "/Users/halit\|claude-501" $DEST --include='*.sh' --include='*.py' --include='*.java' || echo "no machine-specific paths left"
